using System;
using System.Collections.Generic;
using UnityEngine;
public partial class DungeonPrototype {
 public bool SaveDungeonGame(){if(battle||moving||lost)return false;try{var data=CaptureDungeonSave();var previous=DungeonSaveStore.Read();DungeonSaveStore.Write(data,DungeonSaveStore.ActiveSlot,previous!=null?previous.slotName:null);return true;}catch(Exception e){Debug.LogWarning("No se pudo guardar: "+e.Message);return false;}}
 public DungeonSaveData CaptureDungeonSave(){var data=new DungeonSaveData{cell=position,heading=heading,directorRestRemaining=directorRestSteps,entityStates=new List<DungeonEntityState>(mapEntityStates),player=CapturePlayerProgression(),refuge=refuge,introductionCompleted=introductionCompleted||(introduction!=null&&!introduction.Active),enemies=CaptureEnemyProgression(),triggeredEncounters=CaptureTriggeredEncounterIds()};for(int y=0;y<map.Length;y++)for(int x=0;x<map[y].Length;x++)if(explored[x,y])data.explored.Add(new Vector2Int(x,y));return data;}
 public bool LoadDungeonGame(){if(battle||moving)return false;try{var data=DungeonSaveStore.Read();if(data==null)return false;RestoreDungeonSave(data);return true;}catch(Exception e){Debug.LogWarning("No se pudo cargar: "+e.Message);return false;}}
 public void RestoreDungeonSave(DungeonSaveData data){if(data==null||data.player==null||!Open(data.cell))throw new ArgumentException("Partida inválida o plano cambiado");CancelMapReveal();SetPause(false);playerNavigation=null;directorNextSpawnTime=0;nextRespawnScan=0;directorRestSteps=0;directorSectors.Clear();itemReceipts.Clear();StopAllCoroutines();combatSummons.Clear();foreach(var corpse in fadingEnemies)if(corpse!=null)Destroy(corpse);fadingEnemies.Clear();pendingChests.Clear();disappearingBodies.Clear();foreach(var actor in refugeActors.Values){var visual=actor.GetComponent<GhostEnemyVisual>();actor.transform.localScale=visual!=null?Vector3.one*.75f:Vector3.one;if(visual!=null)visual.ResetToIdle();}worldDialogue.Cancel();transferMenu=nodeDecision=refugeExitLooking=devotoApproachLatched=false;battle=busy=moving=lost=levelComplete=false;activeEnemy=-1;encounter.Clear();foreach(var obj in enemyObjects)if(obj!=null)Destroy(obj);enemyObjects.Clear();enemies.Clear();enemyLives.Clear();alerted.Clear();respawnAt.Clear();slots.Clear();defeatedEnemies.Clear();triggeredEncounters.Clear();mapEntityStates=data.entityStates??new List<DungeonEntityState>();refuge=data.refuge??new RefugeProgress();MigrateRefugeNarrative();ownedEquipment.Clear();equippedIds=new string[3];foreach(var item in data.player.inventory){if(Array.Exists(Character.equipment,e=>e!=null&&e.id==item.itemId))ownedEquipment.Add(item.itemId);}itemCounts=new int[inventorySettings.items.Length];foreach(var item in data.player.inventory){int i=Array.FindIndex(inventorySettings.items,e=>e!=null&&e.id==item.itemId);if(i>=0)itemCounts[i]=Mathf.Max(0,item.quantity);}if(data.player.equipmentIds!=null)for(int i=0;i<Mathf.Min(3,data.player.equipmentIds.Length);i++)equippedIds[i]=data.player.equipmentIds[i];coins=Mathf.Max(0,data.player.coins);pendingCombatDrops=data.player.pendingCombatDrops??new List<InventoryItemRecord>();RestorePlayerLevel(data.player);RestoreHackAvailability(data.player);EnsureEquipment();hp=Mathf.Clamp(data.player.currentHP,1,MaximumHP);playerBits=data.player.hasBits?Mathf.Clamp(data.player.currentBits,0,MaximumBits):MaximumBits;introductionCompleted=data.introductionCompleted;if(introductionCompleted){introduction?.Skip();ReleaseIntroductionInput();}else{VirtualDungeon.GameStartContext.PrepareNewGame();StartIntroduction();}
  // Dead slots first: their cells may have been occupied by other agents since defeat.
  foreach(bool dead in new[]{true,false})foreach(var record in data.enemies){if(record.defeated!=dead)continue;if(refugeSettings!=null&&record.placementId==refugeSettings.devotoPlacementId&&refuge.devotoDefeated)continue;var origin=RegionMap==null?RegionAt(record.cell):Array.Find(RegionMap.regions,z=>z.id==record.zoneId);if(origin==null||!Open(record.cell))continue;var actual=RegionMap==null?null:Array.Find(RegionMap.placedEnemies,e=>e.id==record.placementId);if(actual==null&&!string.IsNullOrEmpty(record.placementId))continue;var forced=actual??new PlacedEnemyDefinition{speciesId=record.speciesId,cell=record.cell,randomLevel=false,fixedLevel=record.level,countsTowardLimit=false};int before=enemyObjects.Count;AddEnemy(record.cell,visualKind:ArrayIndex(record.speciesId),origin:origin,placement:forced);if(enemyObjects.Count==before)continue;int index=enemyObjects.Count-1;slots[index].placement=actual;slots[index].counts=actual==null||actual.countsTowardLimit;slots[index].instanceId=record.instanceId;var stats=enemyObjects[index].GetComponent<EnemyCombatStats>();stats.instanceId=record.instanceId;stats.placementId=record.placementId;stats.category=record.category;enemyLives[index]=Mathf.Clamp(record.currentHP,0,stats.maximumHP);alerted[index]=record.alerted;if(record.defeated){Destroy(enemyObjects[index]);enemyObjects[index]=null;defeatedEnemies[index]=record;respawnAt[index]=slots[index].CanRespawn?Time.unscaledTime+record.respawnRemaining:-1;}}
  foreach(var id in data.triggeredEncounters??new string[0])triggeredEncounters.Add(id);explored=new bool[map[0].Length,map.Length];foreach(var c in data.explored)if(c.x>=0&&c.y>=0&&c.x<map[0].Length&&c.y<map.Length)explored[c.x,c.y]=true;WarpPlayer(data.cell,data.heading);if(refugeSettings!=null){UpdateRefugePresentation();EnsureDevotoEvent();TryGrantRefugeReward();}directorRestSteps=Mathf.Max(0,data.directorRestRemaining);EnsureMakongPlacementAfterLoad(data);PopulateRegions(true);RefreshMapEntityStates();message="Partida cargada.";
 }
}
